let outerArcB = null;
let showProof = false;

// Angle labels (recreated on every update)
let labA = null, labB = null, labC = null, sumLab = null;
let title = null;

function vecSub(u, v) { return [u[0]-v[0], u[1]-v[1], 0]; }
function vecAdd(u, v) { return [u[0]+v[0], u[1]+v[1], 0]; }
function vecScale(u, s) { return [u[0]*s, u[1]*s, 0]; }
function vecLen(u) { return Math.hypot(u[0], u[1]); }
function vecNorm(u) {
  const l = vecLen(u) || 1;
  return [u[0]/l, u[1]/l, 0];
}
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

function angleAt(vertex, p1, p2) {
  const v1 = vecNorm(vecSub(p1, vertex));
  const v2 = vecNorm(vecSub(p2, vertex));
  const dot = clamp(v1[0]*v2[0] + v1[1]*v2[1], -1, 1);
  const cross = v1[0]*v2[1] - v1[1]*v2[0];
  return Math.atan2(Math.abs(cross), dot) * 180 / Math.PI;
}

function labelPos(vertex, p1, p2, dist) {
  const v1 = vecNorm(vecSub(p1, vertex));
  const v2 = vecNorm(vecSub(p2, vertex));
  let bis = vecNorm(vecAdd(v1, v2));
  // if nearly collinear fall back to perpendicular
  if (vecLen(bis) < 0.2) bis = [-v1[1], v1[0], 0];
  return vecAdd(vertex, vecScale(bis, dist));
}

function makeAngleArc(vertex, p1, p2, radius, color) {
  const v1 = vecNorm(vecSub(p1, vertex));
  const v2 = vecNorm(vecSub(p2, vertex));
  let a1 = Math.atan2(v1[1], v1[0]);
  let a2 = Math.atan2(v2[1], v2[0]);
  // ensure we sweep the interior (smaller) angle
  let diff = a2 - a1;
  while (diff <= -Math.PI) diff += 2*Math.PI;
  while (diff > Math.PI) diff -= 2*Math.PI;
  const steps = 12;
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = a1 + (diff * i) / steps;
    pts.push([
      vertex[0] + radius * Math.cos(t),
      vertex[1] + radius * Math.sin(t),
      0
    ]);
  }
  const arc = new Polygon({ vertices: pts, color: color });
  arc.setFillOpacity(0).setStrokeWidth(4);
  return arc;
}

