  scene.add(arcA, arcB, arcC);

  labA = new Text({ text: angA.toFixed(0) + '°', color: RED, fontSize: 22 });
  labA.moveTo(labelPos(A, B, C, 0.7));
  labB = new Text({ text: angB.toFixed(0) + '°', color: GREEN, fontSize: 22 });
  labB.moveTo(labelPos(B, A, C, 0.7));
  labC = new Text({ text: angC.toFixed(0) + '°', color: ORANGE, fontSize: 22 });
  labC.moveTo(labelPos(C, A, B, 0.7));

